GLOSSARY_EXTRA = [("FC", "Financial close: the date the financing documents become effective and funds can be drawn."), ("CP", "Condition precedent: an item that must be satisfied before a drawdown."), ("EoD", "Event of default."),
 ("Lock-up", "A test (for example DSCR below a threshold) that blocks distributions to sponsors."), ("MRA", "Major-maintenance reserve account for lifecycle costs such as rolling-stock overhauls."), ("Step-in", "A lender's right to take over or appoint a replacement operator or concessionaire to cure a default."),
 ("Direct agreement", "A contract between the lenders and a project counterparty that protects the lenders' security."), ("Tail", "The period between the final loan maturity and the end of the project or concession."), ("Lender's case", "The conservative forecast (for example P90 traffic) on which the lenders size the debt."),
 ("P50 / P90", "Forecast values that are exceeded with 50% / 90% probability."), ("Restricted payment", "A payment to sponsors (dividend, shareholder-loan interest or principal) that the credit agreement allows only if conditions are met."),
 ("R1C1", "A way of reading a formula by relative position (for example 'two columns left') instead of by cell address; two cells have the same R1C1 formula when they do the same thing relative to their position."),
 ("Gearing", "Senior debt divided by total project cost (debt plus equity)."), ("Tenor", "The repayment period of the loan, here in quarters."), ("Goal Seek", "An Excel tool that changes one input until another cell reaches a target value."),
 ("Flag", "A row of 1s and 0s that switches a calculation on or off."), ("Anchor ($)", "A dollar sign that stops a reference moving when a formula is filled across or down: $F11 keeps column F, J$5 keeps row 5."), ("Roll-forward", "closing balance = opening balance + additions - reductions."),
 ("PIK", "Payment in kind: interest added to the balance instead of paid in cash.")]
