CONCEPT_QA = {
 "B00": [("Why switch iterative calculation off?", "Because a circular reference must be a visible error. Iteration silently hides loops that should be removed algebraically."), ("Why one formula per row?", "So a reviewer can check a row by its first two cells and any difference across the row is a defect, not a design choice.")],
 "B01": [("What do the J, K and L columns of InpC hold and what is in F?", "J, K and L hold the Base, Downside and Upside values; F holds the active value =INDEX(I:M,$F$4) picked by the scenario switch."), ("Why not type the fare inside the revenue formula?", "A typed number hides an assumption, cannot be changed by scenario and cannot be found by an audit of the inputs sheet.")],
 "B02": [("Why multiply by a flag instead of nesting IFs?", "A flag row is visible, checkable (its total must be 80, 60, 1) and reused by every sheet, so timing logic lives in one place."), ("Why is the acquisition column special?", "It is where opening balances are set to their initial values and where cumulative items restart.")],
 "B03": [("Why compound the quarterly rate as (1+annual)^(1/4)-1?", "So four quarters compound to exactly the annual rate; dividing the annual rate by four would overstate inflation."), ("Why are handling and O&M escalated from different CPI dates?", "Each contract was signed when the index stood at a different level, so each escalates from its own base.")],
 "B04": [("Why does cash received lag revenue?", "Customers pay after the receivable days; the unpaid part is carried in receivables until it is collected."), ("What is the roll-forward identity?", "Closing receivables = opening + revenue - cash received.")],
 "B05": [("Why is O&M multiplied by (1 + sensitivity)?", "To let one input shock the cost line in a scenario without editing the contract amount."), ("Why do payables mirror receivables?", "Suppliers are paid after the payable days, so cash paid lags cost incurred in the same way receipts lag revenue.")],
 "B06": [("Why do tax paid and tax expense differ?", "Cash tax uses tax depreciation and deducts interest; the income statement uses accounting depreciation; the difference accumulates as deferred tax."), ("What does a stranded deferred-tax balance tell you?", "That one tax line omits an item (here interest), so tax paid and tax expense never converge.")],
 "B07": [("Why pool capex depreciation instead of tracking each vintage?", "It is simpler and transparent; the cost is a small approximation after year 5."), ("Why is retirement a SUMIFS on the counter?", "Capex leaves the pool exactly 20 periods after it enters, and SUMIFS finds the amount spent that many periods ago.")],
 "B08": [("Why is there no circularity in the interest calculation?", "Interest is charged on the opening balance, which is known before the period starts."), ("What does the INDEX switch buy you?", "Changing one cell changes the whole repayment profile; later you can add a fourth profile without touching a formula.")],
 "B09": [("Which two tests limit a dividend?", "Cash available and distributable profit; the dividend is the smaller of the two."), ("Why is share capital redeemed only in the last forecast quarter?", "The simplification assumes the shareholders recover their capital at the end of the project.")],
 "B10": [("Why build three checks rather than one?", "Each isolates a statement (income, cash, balance sheet), so the first failing check tells you where to look."), ("What should you do first when the balance sheet check is 1?", "Find the first column where it is 1 and compare the movement of every balance sheet row in that column.")],
 "B11": [("Why does XIRR need a non-zero first cash flow?", "XIRR requires a sign change starting from a defined first flow; the -0.001 device supplies it when the first column is zero."), ("Why can NPV and IRR disagree?", "NPV depends on the required return and the scale of the project; IRR is a rate. For non-conventional cash flows IRR can be unreliable.")],
 "B12": [("Why paste values, not formulas, into the stored runs?", "A formula would change when the scenario changes; a value freezes the run."), ("What does column J of Track count?", "The rows that differ between the live results and the selected stored run.")],
 "B13": [("What is the difference between a scenario and a sensitivity?", "A scenario changes several inputs together to tell a story; a sensitivity changes one input to rank drivers."), ("Why must a data table sit on the sheet of its input cell?", "Excel substitutes values into the input cell, which must be on the same sheet as the table.")],
 "B14": [("Why is IDC a circular reference if charged on the average balance?", "Interest depends on the amount drawn, which depends on total uses, which include the interest."), ("How does the model avoid it?", "By charging interest on the opening balance, or by solving the average-balance equation algebraically.")],
 "B15": [("Why do NCA, Tax and Equity update after one edit on InpC row 64?", "They all read InpC row 64, so re-pointing that one cell re-points all of them."), ("What must still tie at COD?", "Assets must equal debt plus equity on the first balance sheet.")],
 "B16": [("Why size debt on tax computed before interest?", "Interest affects tax, which affects CFADS, which affects debt, which affects interest; sizing on pre-interest tax breaks the loop and is conservative."), ("What does the gearing cap do to the facility?", "When it binds, the debt is the cap, not the DSCR capacity, so the facility and the fees are based on the capped amount.")],
 "B17": [("Why did no Debt formula change?", "Debt already selected its profile through INDEX; adding a row and widening the range is enough."), ("What would break if you inserted outside the INDEX range?", "The new profile could not be selected; the INDEX range must include the inserted row.")],
 "B18": [("Why does the DSRA lower the sponsor IRR?", "It traps cash that would otherwise be distributed earlier."), ("Why can the model understate the cost of the DSRA?", "It funds the account from operating cash, whereas in practice it is funded at COD or replaced by a letter of credit.")],
 "B19": [("Why is the blended return the right measure?", "Sponsors invest through two instruments; the loan earns interest and the equity a dividend, so only the combination measures the sponsor return."), ("What limits shareholder-loan payments in practice?", "The credit agreement (restricted payments, lock-up), interest-limitation and transfer-pricing rules and withholding tax.")],
 "B20": [("Why can LLCR exceed the minimum DSCR?", "LLCR averages cover over the loan life with discounting, so one weak quarter weighs less than in the DSCR."), ("Why report LLCR at COD only?", "Later values divide by a shrinking debt balance and become large without meaning.")],
 "B21": [("Why insert rows rather than cut and paste?", "Inserting lets Excel update every reference; cutting and pasting can break them."), ("Which ranges do not grow automatically?", "SUM ranges when the new row sits at the edge of the range.")],
 "B22": [("Why is IRR flat in the DSCR target once the cap binds?", "The gearing cap, not the DSCR, limits debt, so loosening the DSCR adds no debt."), ("Why is a higher IRR not enough to approve a structure?", "The credit committee tests the structure on the lender's case and the downside, on a fixed financing.")],
 "B23": [("Why guard ratios with the tolerance?", "Float noise after maturity makes a zero denominator look non-zero and produces nonsense ratios."), ("What is the minimum content of the Cover status?", "Every check that should be zero: statements, timeline, opening balances and sources-less-uses.")],
}
